    @Test func sessionsMatchJava() throws {
        for (start, duration, epoch, nano, session, first, end) in Self.sessions {
            let tour = try Tour(startMinute: start, durationMinutes: duration)
            let label = "\(start)/\(duration) @\(epoch)"
            #expect(tour.session(epochSecond: epoch) == session, Comment(rawValue: label))
            if let first {
                #expect(try tour.sessionStart(epochSecond: epoch) == first, Comment(rawValue: label))
            } else {
                #expect(throws: Tour.TourError.instantOutOfRange) { try tour.sessionStart(epochSecond: epoch) }
            }
            if let end {
                #expect(try tour.sessionEnd(epochSecond: epoch) == end, Comment(rawValue: label))
            } else {
                #expect(throws: Tour.TourError.instantOutOfRange) { try tour.sessionEnd(epochSecond: epoch) }
            }
            // `Date` with nanoseconds: only where `Double` is exact to a fraction of a second.
            if abs(epoch) < 1_000_000_000_000 && nano <= 500_000_000 {
                let date = Date(timeIntervalSince1970: Double(epoch) + Double(nano) / 1e9)
                #expect(tour.session(at: date) == session, Comment(rawValue: label))
                if let first {
                    #expect(try tour.sessionStart(at: date) == Date(timeIntervalSince1970: Double(first)))
                }
            }
        }
    }

