    @Test func formatMatchesJavaCsLocale() throws {
        for (start, duration, text) in Self.formats {
            let tour = try Tour(startMinute: start, durationMinutes: duration)
            #expect(tour.format() == text)
            // A four-digit duration is parsed as hhmm (1440 = 14:40), as in Java — round trip only below 1000.
            if duration < 1000 { #expect(Tour.parse(tour.format()) == tour) }
        }
    }

