        ("colon", "_OFF", nil),
        ("colon", "OFF_", nil),
        ("colon", "garbage", nil),
        ("colon", "1200/3", nil),
        ("colon", "1800/30", (1080, 30)),
        ("colon", "_1800/30_", (1080, 30)),
        ("colon", "0000/0005", (0, 5)),
    ]

    @Test func effectiveMatchesJava() throws {
        for (kind, raw, expected) in Self.effective {
            let setup: String? = raw == "<null>" ? nil : raw.replacingOccurrences(of: "_", with: " ")
            let actual = Tour.effective(setup, try Self.definition(kind))
            let label = "\(kind) \(raw)"
            #expect(actual.map { [$0.startMinute, $0.durationMinutes] } == expected.map { [$0.0, $0.1] }, Comment(rawValue: label))
        }
    }
}
